# Query rewriting and HyDE (conceptual)
def rewrite_query(question, llm):
    prompt = f"Rewrite this question as a search query:\n{question}"
    return llm.generate(prompt)

def hyde(question, llm, embed):
    prompt = f"Write a short paragraph that answers:\n{question}"
    hypothetical_answer = llm.generate(prompt)
    return embed(hypothetical_answer)

question = "How do I fix a broken pipe in winter?"
print("Rewrite: winter pipe repair steps")
print("HyDE: embed a hypothetical repair passage")

# RAG failure modes and fixes
failures = {
    "Retrieval miss":         "Add hybrid search, better embeddings, reranking",
    "Context dilution":       "Rerank and reduce k, better prompts",
    "Hallucination":          "Stricter prompt: 'answer ONLY from context'",
    "Stale knowledge":        "Refresh the document index regularly",
    "Ambiguous query":        "Query rewriting or clarifying questions",
}

for failure, fix in failures.items():
    print(f"{failure}: {fix}")

# Choosing between RAG, fine-tuning, and long context
strategies = {
    "Large changing corpus":    "RAG",
    "Small static corpus":      "Long context",
    "Teach style/behaviour":    "Fine-tuning",
    "Need citations":           "RAG",
    "Domain-specific language": "Fine-tuning + RAG",
}

for scenario, choice in strategies.items():
    print(f"{scenario}: {choice}")

