# A more complete RAG pipeline (skeleton)
class AdvancedRAG:
    def __init__(self, llm, embed, retrieve, rerank):
        self.llm = llm
        self.embed = embed
        self.retrieve = retrieve
        self.rerank = rerank

    def rewrite(self, question):
        prompt = f"Rewrite as a search query:\n{question}"
        return self.llm.generate(prompt)

    def answer(self, question):
        search_query = self.rewrite(question)
        candidates = self.retrieve(search_query, k=50)
        top_docs = self.rerank(question, candidates, k=5)
        context = "\n\n".join(top_docs)
        prompt = f"Answer using ONLY the context below.\n\nContext:\n{context}\n\nQuestion: {question}"
        return self.llm.generate(prompt)

print("AdvancedRAG: rewrite, hybrid retrieve, rerank, strict prompt")
